
public class T0E2 {
	//PROCESOS
    public static void cien_diez() {
        int i = 101;
        while(i > 10) {
            i = i - 1;
            System.out.print(i + ", ");
        }
    }
  //PROGRAMA PRINCIPAL
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("Serie decreciente: ");
        cien_diez();
	}

}
